-- ============================================
-- LUMA — Thème 15 : LONG 3/3 x4 — Un événement local (marché, festival de quartier) à vivre de bout en bout
-- ============================================


update scenarios set content = '{"characters": {"alice": "Alice", "vendor1": "vendeur 1", "vendor2": "vendeur 2", "vendor3": "vendeur 3"}, "start_node": "n1", "nodes": {"n1": {"speaker": "alice", "text": "Borough Market on a Saturday — apparently this is the place to be for food lovers.", "text_fr": "Borough Market un samedi — apparemment c''est l''endroit à voir pour les amateurs de nourriture.", "choices": [{"text": "I can already smell incredible food from here. Let''s dive in!", "text_fr": "Je peux déjà sentir une nourriture incroyable d''ici. Plongeons dedans !", "next": "n2"}, {"text": "Should we make a plan, or just wander and discover things?", "text_fr": "On devrait faire un plan, ou juste se balader et découvrir des choses ?", "next": "n2b"}]}, "n2": {"speaker": "vendor1", "text": "Fresh oysters, love? Best in London, I promise you that!", "text_fr": "Des huîtres fraîches, chérie ? Les meilleures de Londres, je vous le promets !", "choices": [{"text": "I''ll try a few, why not!", "text_fr": "Je vais en essayer quelques-unes, pourquoi pas !", "next": "n3"}]}, "n2b": {"speaker": "alice", "text": "Let''s just wander, honestly. Half the fun is stumbling onto things.", "text_fr": "Baladons-nous juste, honnêtement. La moitié du plaisir c''est de tomber sur des choses par hasard.", "choices": [{"text": "Agreed, let''s follow our noses, literally.", "text_fr": "D''accord, suivons notre nez, littéralement.", "next": "n3"}]}, "n3": {"speaker": "you_thought", "text": "(You wander deeper into the market, discovering stalls of every imaginable cuisine.)", "text_fr": "(Vous vous enfoncez plus profondément dans le marché, découvrant des étals de toutes les cuisines imaginables.)", "choices": [{"text": "(Try a sample from a stall selling artisanal cheeses.)", "text_fr": "(Goûte un échantillon d''un étal vendant des fromages artisanaux.)", "next": "n4"}]}, "n4": {"speaker": "vendor2", "text": "This one''s aged eighteen months, quite the flavor journey.", "text_fr": "Celui-ci est affiné dix-huit mois, tout un voyage de saveurs.", "choices": [{"text": "That''s incredible, I''ll take a small piece to bring home.", "text_fr": "C''est incroyable, je vais en prendre un petit morceau à ramener chez moi.", "next": "n5"}]}, "n5": {"speaker": "alice", "text": "(Excitedly) You have to try this bakery stall, the smell alone is unreal!", "text_fr": "(Avec excitation) Tu dois essayer cet étal de boulangerie, l''odeur à elle seule est irréelle !", "choices": [{"text": "Lead the way, I''m definitely following that smell.", "text_fr": "Montre le chemin, je suis définitivement cette odeur.", "next": "n6"}]}, "n6": {"speaker": "vendor3", "text": "Fresh out of the oven, this sourdough. Best seller here every Saturday.", "text_fr": "Tout juste sorti du four, ce levain. Le meilleur vendeur ici chaque samedi.", "choices": [{"text": "I can see why, this smells absolutely incredible.", "text_fr": "Je comprends pourquoi, ça sent absolument incroyable.", "next": "n7"}]}, "n7": {"speaker": "you_thought", "text": "(Hours pass as you both sample your way through nearly every corner of the market.)", "text_fr": "(Des heures passent alors que vous échantillonnez tous les deux presque chaque recoin du marché.)", "choices": [{"text": "(Sit down at a small table to finally enjoy everything you''ve gathered.)", "text_fr": "(Assois-toi à une petite table pour enfin profiter de tout ce que tu as rassemblé.)", "next": "n8"}]}, "n8": {"speaker": "alice", "text": "This has honestly been one of the best food experiences of my life.", "text_fr": "Ça a honnêtement été l''une des meilleures expériences culinaires de ma vie.", "choices": [{"text": "Same here, every single stall had something special about it.", "text_fr": "Pareil pour moi, chaque étal avait quelque chose de spécial.", "next": "n9"}]}, "n9": {"speaker": "vendor1", "text": "(As you pass by again) Back for more oysters, love?", "text_fr": "(En repassant devant) De retour pour plus d''huîtres, chérie ?", "choices": [{"text": "Actually, yes! I couldn''t resist coming back.", "text_fr": "En fait, oui ! J''ai pas pu résister à revenir.", "next": "n10"}, {"text": "Maybe just one more round before we head out!", "text_fr": "Peut-être juste un tour de plus avant qu''on parte !", "next": "n10"}]}, "n10": {"speaker": "you_thought", "text": "(As the market begins to wind down for the day, you both feel wonderfully full and content.)", "text_fr": "(Alors que le marché commence à ralentir pour la journée, vous vous sentez tous les deux merveilleusement rassasiés et satisfaits.)", "choices": [{"text": "What a perfect way to spend a Saturday, honestly.", "text_fr": "Quelle façon parfaite de passer un samedi, honnêtement.", "next": "end_market"}]}, "end_market": {"speaker": "alice", "text": "Truly perfect. This market alone might be worth coming back to London for.", "text_fr": "Vraiment parfait. Ce marché à lui seul pourrait valoir le coup de revenir à Londres.", "end": true, "ending_label": "Une expérience de marché local inoubliable 🧀🍞🦪"}}}'::jsonb, is_playable = true
where title = 'Un événement local (marché, festival de quartier) à vivre de bout en bout'
  and theme_id = (select id from scenario_themes where position = 15 and language_id = (select id from languages where code = 'en'));
